"use strict";

// billing notifications: data access and state changes for the billing service.

const { ValidationError } = require("../../lib/errors");
const log = require("../../lib/logger").child({ module: "billing/notifications" });

/**
 * Create a record in the billing notifications.
 * Returns the updated record, or null when no record has this id.
 */
async function createRecord(db, id, input = {}) {
  const record = await db.billingNotifications.findById(id);
  if (!record) {
    log.warn("create billing record: not found", id);
    return null;
  }
  const next = {
    ...record,
    title: input.title ?? record.title,
    status: input.status ?? record.status,
    lastAction: "create",
    updatedAt: new Date().toISOString(),
  };
  if (next.title === undefined || next.title === null) {
    throw new ValidationError("record title is required");
  }
  await db.billingNotifications.update(id, next);
  log.info("create billing record", id);
  return next;
}

/**
